    def __init__(self, nodes_factory, add_feature_toggle=True):
        self.web_url = nodes_factory.web_url
        self.web_username = nodes_factory.web_username
        self.web_password = nodes_factory.web_password
        self.nodes_factory = nodes_factory
        self._configuration_service = None
        self._module_configuration_service = None
        self._definitions_service = None
        self._pmcm_data_service = None
        self._reporting_service = None
        if add_feature_toggle:
            self._configure_feature_toggle()

    def _configure_feature_toggle(self):
        """
        Configure XML file with SWAM feature toggle on NetAct was node.
        NOTE: Required since NetAct 18 release.
        """
        toggle_file_name = 'Pref_AP_SWAM_FeatureToggles.xml'
        target_directory = '/d/oss/global/var/javaprefs/SWAM/'
        local_toggle_path = os.path.join(os.path.dirname(__file__), toggle_file_name)
        target_toggle_path = os.path.join(target_directory, toggle_file_name)
        with self.was_node as ssh:
            if ssh.file_exists(target_toggle_path):
                file_content = ssh.get_file_content(target_toggle_path)
                tree = etree.fromstring(file_content).getroottree()
                testing_entry = tree.find(".//node[@name='FeatureToggle']/map/entry[@key='TESTING']")
                if testing_entry is not None and testing_entry.get('value') != 'on':
                    logger.info(f'Changing to <entry key="TESTING" value="on"/> in {target_toggle_path}')
                    testing_entry.attrib['value'] = 'on'
                elif testing_entry is None:
                    logger.info(f'Adding <entry key="TESTING" value="on"/> in {target_toggle_path}')
                    entry_tags_parent = tree.find(".//node[@name='FeatureToggle']/map")
                    etree.SubElement(entry_tags_parent, 'entry', {"key": "TESTING", "value": "on"})
                else:
                    return
                file_content = etree.tostring(tree, xml_declaration=True, encoding=tree.docinfo.encoding)
                ssh.put_file_content(file_content, target_toggle_path)
            else:
                logger.info(f'Uploading {toggle_file_name} to {target_directory}')
                ssh.put_file(local_toggle_path, target_toggle_path)

